import { Table, StringColumn, BooleanColumn, GenericColumn } from '../../db'

export const sys_hub_flow = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    extends: 'sys_hub_flow_base',
    label: 'Flow',
    name: 'sys_hub_flow',
    schema: {
        master_snapshot_digest: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Main snapshot Digest',
            maxLength: 4000,
        }),
        show_triggered_flows: BooleanColumn({
            default: false,
            label: 'Show triggered flows',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        version_record: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Version record',
        }),
        substatus: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Substatus',
            maxLength: 255,
        }),
        updation_source: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Updation source',
            maxLength: 255,
        }),
        show_draft_actions: BooleanColumn({
            default: false,
            label: 'Show draft actions',
        }),
        display_name_after_preview: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Display name after preview',
            maxLength: 255,
        }),
        latest_snapshot: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Latest snapshot',
            maxLength: 32,
        }),
        pre_compiled: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'System will attempt to compile flow without a need of a run of the flow. (Does not guarantee flow will be compiled before run if the flow runs very frequently)',
                    label: 'Pre-Compiled',
                    plural: 'Pre-Compiled',
                },
            ],
        }),
        master_snapshot: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Main snapshot',
            maxLength: 32,
        }),
        generation_source: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Generation source',
            maxLength: 255,
        }),
        compiler_build: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Compiler build',
            maxLength: 255,
        }),
    },
})
